//! Generated by tools/gen_art.mjs from the art in design/. Do not edit.

/// An indexed image: pal[px] is the RGB565 colour, index 0 is transparent.
#[derive(Clone, Copy, Debug)]
pub struct Img {
    pub w: u16,
    pub h: u16,
    pub pal: &'static [u16],
    off: u32,
}

static PX: &[u8] = include_bytes!("art.bin");

impl Img {
    /// Row-major palette indexes, w * h of them.
    pub fn px(&self) -> &'static [u8] {
        &PX[self.off as usize..][..self.w as usize * self.h as usize]
    }
}

